import React, { useState } from 'react';

function TourPackages() {
  const [activeTab, setActiveTab] = useState(0);

  const tickets = [
    {
      title: "아비정전 4K 리마스터링",
      subtitle: "메가박스가 제안하는 <아비정전 4K 리마스터링>을 가장 잘 간직하는 방법",
      category: "ORIGINAL TICKET",
      img: "https://image.tmdb.org/t/p/w500/z1pufUDaUixWwIdXpeF54g2nS4G.jpg",
      replay: "2026.09.12",
      director: "왕가위",
      cast: "장국영, 장만옥, 유덕화, 유가령, 장학우, 임청하"
    },
    {
      title: "헤어질 결심 특별전",
      subtitle: "다시 마주하는 명작의 감동, 오리지널 티켓으로 소장하세요.",
      category: "ORIGINAL TICKET",
      img: "https://image.tmdb.org/t/p/w500/lWjrLW8YBWDvvnbz2rW1kUaJ70P.jpg",
      replay: "2026.09.20",
      director: "박찬욱",
      cast: "박해일, 탕웨이"
    }
  ];

  const currentTicket = tickets[activeTab];

  return (
    <div className="w-full bg-[#fbfbfa] py-16 px-4 flex flex-col items-center border-t border-zinc-200">
      <div className="w-full max-w-6xl">
        
        {/* 섹션 타이틀 */}
        <div className="flex justify-between items-center mb-8">
          <h3 className="text-2xl font-black text-zinc-900 tracking-tight">혜택 및 이벤트</h3>
          <span className="text-sm font-bold text-[#503396] cursor-pointer hover:underline">+ 더보기</span>
        </div>

        {/* 오리지널 티켓 쇼케이스 박스 */}
        <div className="bg-white border border-zinc-200 rounded-3xl p-8 md:p-12 shadow-lg flex flex-col md:flex-row items-center justify-between gap-12">
          
          {/* 좌측 텍스트 및 설명 영역 */}
          <div className="flex-1 space-y-4">
            <span className="text-xs font-black tracking-widest text-[#503396] uppercase bg-purple-100 px-3 py-1 rounded-full">
              메가박스 오리지널 티켓
            </span>
            <h2 className="text-3xl md:text-5xl font-black text-zinc-900 tracking-tight">
              {currentTicket.category}
            </h2>
            <p className="text-sm font-medium text-zinc-600 leading-relaxed max-w-md">
              {currentTicket.subtitle}
            </p>
            
            {/* 상세 정보 */}
            <div className="pt-4 border-t border-zinc-100 grid grid-cols-2 gap-4 text-xs text-zinc-500 font-bold">
              <div>감독 : <span className="text-zinc-900">{currentTicket.director}</span></div>
              <div>개봉일 : <span className="text-zinc-900">{currentTicket.replay}</span></div>
            </div>

            {/* 슬라이더 컨트롤 및 인디케이터 */}
            <div className="flex items-center gap-4 pt-4">
              <div className="w-24 h-1 bg-zinc-200 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-[#553396] transition-all duration-300" 
                  style={{ width: `${((activeTab + 1) / tickets.length) * 100}%` }}
                />
              </div>
              <div className="flex items-center gap-3 text-xs font-black text-zinc-700">
                <button 
                  onClick={() => setActiveTab((prev) => (prev - 1 + tickets.length) % tickets.length)}
                  className="hover:text-[#503396]"
                >
                  &larr;
                </button>
                <button 
                  onClick={() => setActiveTab((prev) => (prev + 1) % tickets.length)}
                  className="hover:text-[#503396]"
                >
                  &rarr;
                </button>
                <span className="text-zinc-400">|</span>
                <span>{activeTab + 1} / {tickets.length}</span>
              </div>
            </div>
          </div>

          {/* 우측 티켓 시각 카드 영역 */}
          <div className="relative w-full md:w-80 h-96 rounded-2xl overflow-hidden shadow-2xl border border-zinc-300 bg-zinc-900 flex flex-col">
            <div className="bg-zinc-100 px-4 py-2 border-b border-dashed border-zinc-300 flex justify-between items-center text-[10px] text-zinc-500 font-bold">
              <span className="text-[#503396]">MEGABOX ORIGINAL TICKET</span>
              <span>NO. 0{activeTab + 1}</span>
            </div>
            <div className="relative flex-1 overflow-hidden">
              <img 
                src={currentTicket.img} 
                alt={currentTicket.title} 
                className="w-full h-full object-cover" 
              />
            </div>
            <div className="bg-zinc-950 px-4 py-2.5 text-center text-white text-xs font-black tracking-wide">
              {currentTicket.title}
            </div>
          </div>

        </div>

      </div>
    </div>
  );
}

export default TourPackages;
